76	
77	    /** Dedicated audit logger for owner lifecycle side-effects. */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    /** Serializes {@link OwnerCreatedEvent} instances to their JSON audit representation. */
81	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
82	
83	    /** Monotonically increasing sequence stamped on every structured owner-created event. */
84	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
85	
86	    /**
87	     * Immutable structured audit event emitted once per owner create. The {@code memberId}
88	     * field carries the owner's <em>current primary identifier</em> as returned by
89	     * {@link #primaryIdentifier(Owner)} (the unified memberId).
90	     */
91	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
92	            Integer membershipLevel, String event) {
93	    }
94	
95	    /**
96	     * Pragmatic check for a syntactically valid email address: a non-empty local
97	     * part, a single '@', and a domain with at least one dot-separated label.
98	     */
99	    private static final Pattern EMAIL_PATTERN =
100	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
101	
102	    /**
103	     * Disposable email domains that are rejected: an owner email whose domain is one of
104	     * these is treated as invalid so the create/update is rejected with 400. Compared
105	     * case-insensitively against the normalized (lower-cased) email domain.
106	     */
107	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
108	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
109	
110	    /**
111	     * Common street-type abbreviations expanded during address normalization,
112	     * keyed by their upper-cased form.
113	     */
114	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
115	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
116	
117	    /**
118	     * Required national-number length keyed by E.164 country calling code: a
119	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
120	     * (NANP) number carries 10. A number whose country code is listed here must have
121	     * exactly the mandated number of national digits.
122	     */
123	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
124	        Map.of("61", 9, "1", 10);
125	
126	    /**
127	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
128	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
129	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
130	     * postcode.
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
133	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
134	            "QLD", new int[] {4000, 4099});
135	
136	    /** HTTP header carrying the client-supplied idempotency key for owner creation. */
137	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
138	
139	    /**
140	     * Remembers the owner created for each seen {@code Idempotency-Key}, so a create that
141	     * repeats with an already-seen key returns the originally created owner (200) instead of
142	     * creating a duplicate. Kept in-memory and keyed by the raw header value.
143	     */
144	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
145	
146	    private final ClinicService clinicService;
147	
148	    private final OwnerMapper ownerMapper;
149	
150	    private final PetMapper petMapper;
151	
152	    private final VisitMapper visitMapper;
153	
154	    public OwnerRestControllerV1(ClinicService clinicService,
155	                                 OwnerMapper ownerMapper,
156	                                 PetMapper petMapper,
157	                                 VisitMapper visitMapper) {
158	        this.clinicService = clinicService;
159	        this.ownerMapper = ownerMapper;
160	        this.petMapper = petMapper;
161	        this.visitMapper = visitMapper;
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
167	        Collection<Owner> owners;
168	        if (lastName != null) {
169	            owners = this.clinicService.findOwnerByLastName(lastName);
170	        } else {
171	            owners = this.clinicService.findAllOwners();
172	        }
173	        if (owners.isEmpty()) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
192	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
193	        // previous successful create, return the originally created owner with 200 instead of
194	        // creating a duplicate.
195	        String idempotencyKey = currentIdempotencyKey();
196	        if (idempotencyKey != null) {
197	            Integer existingId = idempotentCreates.get(idempotencyKey);
198	            if (existingId != null) {
199	                Owner existing = this.clinicService.findOwnerById(existingId);
200	                if (existing != null) {
201	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
202	                }
203	            }
204	        }
205	        // Validate & normalize the optional email; reject the create when it is present but invalid.
206	        if (!normalizeEmail(ownerFieldsDto)) {
207	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
208	        }
209	        // Validate & normalize the optional postcode; reject the create when it is present but
210	        // not valid for the owner's city (see normalizePostcode).
211	        if (!normalizePostcode(ownerFieldsDto)) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
215	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
216	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
217	        // when no address is supplied in either form (see normalizeAddresses).
218	        if (!normalizeAddresses(ownerFieldsDto)) {
219	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
220	        }
221	        // Reject the create when the owner's city is already at capacity, i.e. it already
222	        // contains 50 or more owners (compared case-insensitively).
223	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
224	        if (ownersInCity >= 50) {
225	            return new ResponseEntity<>(HttpStatus.CONFLICT);
226	        }
227	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
228	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
229	        if (normalizedTelephone == null) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        ownerFieldsDto.setTelephone(normalizedTelephone);
233	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
234	        // single derived identity key: the SHA-256 hex of
235	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
236	        // A create is rejected with 409 only when the new owner's identity key collides with an
237	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
238	        // the same last name and postcode but different telephones no longer collide — they are
239	        // created (and may be flagged as a soft match below), not rejected. The former separate
240	        // household-duplicate 409 keyed on the computed householdId no longer applies.
241	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
242	        String identityKey = ownerMapper.identityKey(candidate);
243	        boolean identityInUse = this.clinicService.findAllOwners().stream()
244	            .filter(existing -> !existing.isDeleted())
245	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
246	        if (identityInUse) {
247	            return new ResponseEntity<>(HttpStatus.CONFLICT);
248	        }
249	        // Determine the effective registration date — the value supplied on the request, or the
250	        // server's current date when none was supplied — and roll it forward to the next business
251	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
252	        // registration date (membership-number year segment, per-day create-limit) uses this
253	        // adjusted date.
254	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
255	        if (registrationDate == null) {
256	            registrationDate = LocalDate.now();
257	        }
258	        // Reject a supplied registration date that lies in the future (later than the
259	        // server's current date): an owner cannot be registered ahead of time.
260	        else if (registrationDate.isAfter(LocalDate.now())) {
261	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
262	        }
263	        registrationDate = toBusinessDay(registrationDate);
264	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
265	        // owners have already been registered on this (adjusted) business day.
266	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
267	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
268	        }
269	        HttpHeaders headers = new HttpHeaders();
270	        Owner owner = candidate;
271	        owner.setRegistrationDate(registrationDate);
272	        // Assign the unified memberId as '<REGION><FY><HASH8><CHK>': the region derived from the
273	        // owner's postcode (falling back to the city, then 'UNKNOWN'), the two-digit fiscal year of
274	        // the registration date, the first 8 upper-case hex characters of the SHA-256 of the
275	        // normalized telephone concatenated with the last name, and a single Luhn check digit over
276	        // the digits of '<REGION><FY><HASH8>'.
277	        owner.setMemberId(memberId(owner));
278	        // Record how many existing owners already share this owner's first and last name
279	        // (compared case-insensitively) at the moment before this owner is created.
280	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
281	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
282	        // registered on this (adjusted) business day before this owner is created.
283	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
284	        // Flag that the owner's city is approaching its capacity limit: it already held between
285	        // 40 and 49 owners (inclusive) before this owner was created. The hard rejection at 50
286	        // owners is handled above, so reaching this point means the count is below 50.
287	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
288	        // Record the size of this owner's household after this create: the number of existing
289	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
290	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
291	        // Cap this owner's membership level at one above the current maximum membership level among
292	        // their existing household members. When the owner has no existing household member no cap
293	        // applies (a null cap; see OwnerMapper#membershipLevel).
294	        owner.setMembershipLevelCap(membershipLevelCap(owner));
295	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate (its
296	        // identity key is distinct), but it shares an existing owner's Soundex last name and
297	        // postcode. When such a match exists, record it as 'possibleDuplicate' with
298	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
299	        // duplicate. A declared household member (the request sets 'sharesHousehold') is an
300	        // acknowledged member, not a suspected duplicate, so it is never flagged.
301	        Owner softMatch = findPossibleDuplicate(owner);
302	        boolean declaredMember = softMatch != null && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
303	        if (declaredMember) {
304	            owner.setPossibleDuplicate(false);
305	            owner.setPossibleDuplicateOf(null);
306	        }
307	        else {
308	            owner.setPossibleDuplicate(softMatch != null);
309	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
310	        }
311	        this.clinicService.saveOwner(owner);
312	        // Emit an audit line recording the new owner's id, memberId, registration date and
313	        // membership level.
314	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
315	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
316	            ownerMapper.membershipLevel(owner));
317	        // Emit the immutable structured OWNER_CREATED event carrying a monotonically increasing
318	        // sequence and the owner's current primary identifier (the memberId).
319	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
320	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
321	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
322	        // Remember this create against its idempotency key so a later repeat returns the same
323	        // owner instead of creating a duplicate.
324	        if (idempotencyKey != null) {
325	            idempotentCreates.put(idempotencyKey, owner.getId());
326	        }
327	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
328	        headers.setLocation(UriComponentsBuilder.newInstance()
329	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
330	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
331	    }
332	
333	    /**
334	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
335	     * absent, blank, or there is no bound request.
336	     */
337	    private static String currentIdempotencyKey() {
338	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
339	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
340	            return null;
341	        }
342	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
343	        return (key == null || key.isBlank()) ? null : key;
344	    }
345	
346	    /**
347	     * Validate and normalize the optional owner email in place.
348	     *
349	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
350	     * When present it must be a syntactically valid address; a valid address is
351	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
352	     * present but syntactically invalid, so the caller can reject with 400.
353	     */
354	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
355	        String email = ownerFieldsDto.getEmail();
356	        if (email == null || email.isBlank()) {
357	            ownerFieldsDto.setEmail(null);
358	            return true;
359	        }
360	        String normalized = email.trim().toLowerCase(Locale.ROOT);
361	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
362	            return false;
363	        }
364	        // Reject addresses whose domain is on the disposable-domain blocklist.
365	        String domain = normalized.substring(normalized.indexOf('@') + 1);
366	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
367	            return false;
368	        }
369	        ownerFieldsDto.setEmail(normalized);
370	        return true;
371	    }
372	
373	    /**
374	     * Validate the optional owner postcode in place.
375	     *
376	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
377	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
378	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
379	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
380	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
381	     * when a postcode is present but malformed or out of range, so the caller can
382	     * reject with 400.
383	     */
384	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
385	        String postcode = ownerFieldsDto.getPostcode();
386	        if (postcode == null || postcode.isBlank()) {
387	            ownerFieldsDto.setPostcode(null);
388	            return true;
389	        }
390	        if (!postcode.matches("\\d{4}")) {
391	            return false;
392	        }
393	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
394	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
395	        if (range != null) {
396	            int value = Integer.parseInt(postcode);
397	            if (value < range[0] || value > range[1]) {
398	                return false;
399	            }
400	        }
401	        return true;
402	    }
403	
404	    /**
405	     * Validate and normalize the owner's address fields in place, preferring the structured
406	     * form over the flat 'address' for backward compatibility.
407	     *
408	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
409	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
410	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
411	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
412	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
413	     * cleared. Returns {@code false} when no address is supplied in either form (both the
414	     * structured addressLine1 and the flat address are blank once normalized), so the caller
415	     * can reject with 400.
416	     */
417	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
418	        String rawLine1 = ownerFieldsDto.getAddressLine1();
419	        if (rawLine1 != null && !rawLine1.isBlank()) {
420	            String line1 = normalizeAddress(rawLine1);
421	            if (line1.isBlank()) {
422	                return false;
423	            }
424	            ownerFieldsDto.setAddressLine1(line1);
425	            String rawLine2 = ownerFieldsDto.getAddressLine2();
426	            String composed = line1;
427	            if (rawLine2 != null && !rawLine2.isBlank()) {
428	                String line2 = normalizeAddress(rawLine2);
429	                ownerFieldsDto.setAddressLine2(line2);
430	                composed = line1 + " " + line2;
431	            }
432	            else {
433	                ownerFieldsDto.setAddressLine2(null);
434	            }
435	            ownerFieldsDto.setAddress(composed);
436	            return true;
437	        }
438	        // No structured address: fall back to the flat 'address' input.
439	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
440	        if (canonicalAddress.isBlank()) {
441	            return false;
442	        }
443	        ownerFieldsDto.setAddress(canonicalAddress);
444	        ownerFieldsDto.setAddressLine1(null);
445	        ownerFieldsDto.setAddressLine2(null);
446	        return true;
447	    }
448	
449	    /**
450	     * Normalize an owner address: trim, collapse each run of whitespace to a single
451	     * space, upper-case, and expand common street-type abbreviations
452	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
453	     * A {@code null} value normalizes to the empty string.
454	     */
455	    private static String normalizeAddress(String value) {
456	        if (value == null) {
457	            return "";
458	        }
459	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
460	        if (collapsed.isEmpty()) {
461	            return "";
462	        }
463	        String[] tokens = collapsed.split(" ");
464	        StringBuilder sb = new StringBuilder(collapsed.length());
465	        for (int i = 0; i < tokens.length; i++) {
466	            if (i > 0) {
467	                sb.append(' ');
468	            }
469	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
470	        }
471	        return sb.toString();
472	    }
473	
474	    /**
475	     * Normalize a telephone number to E.164 form.
476	     *
477	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
478	     * explicit leading {@code '+'} and country code it is kept; otherwise the
479	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
480	     * dropped from the national digits. The result must contain 8 to 15 digits
481	     * after the {@code '+'}, and — for a recognised country calling code — exactly
482	     * the national-number length that code mandates ({@code '+61'} => 9 national
483	     * digits, {@code '+1'} => 10).
484	     *
485	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
486	     *         the input is absent or cannot form a valid E.164 number.
487	     */
488	    private static String toE164(String raw) {
489	        if (raw == null) {
490	            return null;
491	        }
492	        String trimmed = raw.trim();
493	        boolean hasCountryCode = trimmed.startsWith("+");
494	        // Strip spaces, dashes and brackets.
495	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
496	        String digits;
497	        if (hasCountryCode) {
498	            // Keep the explicit country code; drop the leading '+' for validation.
499	            digits = stripped.substring(1);
500	        } else {
501	            // No country code: assume '+61' and drop a single leading '0'.
502	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
503	            digits = "61" + national;
504	        }
505	        if (!digits.matches("\\d{8,15}")) {
506	            return null;
507	        }
508	        // For a recognised country calling code, enforce the exact national-number length it
509	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
510	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
511	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
512	                .sorted((a, b) -> b.length() - a.length()).toList()) {
513	            if (digits.startsWith(countryCode)) {
514	                int nationalLength = digits.length() - countryCode.length();
515	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
516	                    return null;
517	                }
518	                break;
519	            }
520	        }
521	        return "+" + digits;
522	    }
523	
524	    /**
525	     * Count the existing owners whose first and last name match the given names,
526	     * compared case-insensitively. Used to record an owner's namesake count at the
527	     * moment before it is created.
528	     */
529	    private int countNamesakes(String firstName, String lastName) {
530	        return (int) this.clinicService.findAllOwners().stream()
531	            .filter(existing -> existing.getFirstName() != null
532	                && existing.getFirstName().equalsIgnoreCase(firstName)
533	                && existing.getLastName() != null
534	                && existing.getLastName().equalsIgnoreCase(lastName))
535	            .count();
536	    }
537	
538	    /**
539	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
540	     * computed householdId (derived from the normalized last name and postcode). Used, together
541	     * with the owner being created, to derive the household size recorded on the owner.
542	     */
543	    private int countHouseholdMembers(Owner owner) {
544	        String householdId = ownerMapper.householdId(owner);
545	        return (int) this.clinicService.findAllOwners().stream()
546	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
547	            .count();
548	    }
549	
550	    /**
551	     * Compute the membership-level cap for the owner being created: one above the current maximum
552	     * effective membership level among its existing (non-deleted) household members, i.e. those
553	     * sharing its computed householdId. Each member's effective level is read through
554	     * {@link OwnerMapper#membershipLevel(Owner)}, so it already reflects any cap applied to that
555	     * member. Returns {@code null} when the owner has no existing household member, in which case
556	     * no cap applies.
557	     */
558	    private Integer membershipLevelCap(Owner owner) {
559	        String householdId = ownerMapper.householdId(owner);
560	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
561	            .filter(existing -> !existing.isDeleted())
562	            .filter(existing -> existing != owner)
563	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
564	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
565	            .max();
566	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
567	    }
568	
569	    /**
570	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
571	     * of: one whose identity key differs (so it is not a hard duplicate) yet whose last name shares
572	     * the same Soundex code and whose postcode is the same. Owners without a postcode never match
573	     * (the postcode must be shared) and deleted owners are ignored. When several existing owners
574	     * match, the one with the lowest id is returned so the result is deterministic. Returns
575	     * {@code null} when there is no such match.
576	     */
577	    private Owner findPossibleDuplicate(Owner candidate) {
578	        if (candidate.getPostcode() == null) {
579	            return null;
580	        }
581	        String candidateKey = ownerMapper.identityKey(candidate);
582	        String candidateSoundex = Soundex.of(candidate.getLastName());
583	        return this.clinicService.findAllOwners().stream()
584	            .filter(existing -> !existing.isDeleted())
585	            .filter(existing -> !candidateKey.equals(ownerMapper.identityKey(existing)))
586	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode())
587	                && candidateSoundex.equals(Soundex.of(existing.getLastName())))
588	            .min(java.util.Comparator.comparing(Owner::getId))
589	            .orElse(null);
590	    }
591	
592	    /**
593	     * The owner's current primary identifier, as carried by structured audit events: the
594	     * unified memberId.
595	     */
596	    private String primaryIdentifier(Owner owner) {
597	        return owner.getMemberId();
598	    }
599	
600	    /**
601	     * Build the owner's unified memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}.
602	     *
603	     * <p>{@code REGION} is the region derived from the owner's postcode (see
604	     * {@link #deriveRegion}). {@code FY} is the two-digit fiscal year (starting 1 July) of the
605	     * business-day-adjusted registration date. {@code HASH8} is the first 8 upper-case hex
606	     * characters of the SHA-256 of the normalized telephone concatenated with the last name.
607	     * {@code CHK} is a single Luhn check digit computed over the digits of
608	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW271A2B3C4D5'}).
609	     *
610	     * <p>When the computed memberId collides with an existing owner's memberId, it is
611	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
612	     * that makes it unique.
613	     */
614	    private String memberId(Owner owner) {
615	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
616	        String fy = String.format("%02d", fiscalYearTwoDigits(owner.getRegistrationDate()));
617	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
618	        String base = region + fy + hash8;
619	        String memberId = base + luhn(base);
620	        Set<String> existing = this.clinicService.findAllOwners().stream()
621	            .map(Owner::getMemberId)
622	            .filter(java.util.Objects::nonNull)
623	            .collect(Collectors.toSet());
624	        if (!existing.contains(memberId)) {
625	            return memberId;
626	        }
627	        int n = 2;
628	        while (existing.contains(memberId + "-" + n)) {
629	            n++;
630	        }
631	        return memberId + "-" + n;
632	    }
633	
634	    /**
635	     * The two-digit fiscal year (starting 1 July) of the given date: the last two digits of the
636	     * calendar year in which the fiscal year ends. Dates on or after 1 July belong to the fiscal
637	     * year ending the following calendar year (e.g. 2026-08-10 -&gt; 27); earlier dates belong to
638	     * the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt; 26).
639	     */
640	    private static int fiscalYearTwoDigits(LocalDate date) {
641	        int endYear = date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
642	        return endYear % 100;
643	    }
644	
645	    /**
646	     * A single Luhn check digit (0-9) computed over the digit characters contained in
647	     * {@code value}; non-digit characters are ignored.
648	     */
649	    private static int luhn(String value) {
650	        int sum = 0;
651	        boolean dbl = true;
652	        for (int i = value.length() - 1; i >= 0; i--) {
653	            char c = value.charAt(i);
654	            if (c < '0' || c > '9') {
655	                continue;
656	            }
657	            int d = c - '0';
658	            if (dbl) {
659	                d *= 2;
660	                if (d > 9) {
661	                    d -= 9;
662	                }
663	            }
664	            sum += d;
665	            dbl = !dbl;
666	        }
667	        return (10 - (sum % 10)) % 10;
668	    }
669	
670	    /**
671	     * Derive the owner's region, preferring the postcode. The postcode is matched against
672	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
673	     * it is absent or in no known range does this fall back to the fixed city-to-region table
674	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
675	     */
676	    private static String deriveRegion(String postcode, String city) {
677	        if (postcode != null && postcode.matches("\\d{4}")) {
678	            int value = Integer.parseInt(postcode);
679	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
680	                int[] range = entry.getValue();
681	                if (value >= range[0] && value <= range[1]) {
682	                    return entry.getKey();
683	                }
684	            }
685	        }
686	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
687	    }
688	
689	    /**
690	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
691	     * bytes of {@code value}.
692	     */
693	    private static String sha256HexUpper(String value, int length) {
694	        try {
695	            byte[] digest = MessageDigest.getInstance("SHA-256")
696	                .digest(value.getBytes(StandardCharsets.UTF_8));
697	            StringBuilder sb = new StringBuilder(digest.length * 2);
698	            for (byte b : digest) {
699	                sb.append(String.format("%02X", b));
700	            }
701	            return sb.substring(0, length);
702	        }
703	        catch (NoSuchAlgorithmException e) {
704	            throw new IllegalStateException(e);
705	        }
706	    }
707	
708	    /**
709	     * Count the existing owners located in the given city, compared case-insensitively.
710	     * Used to enforce the per-city capacity limit and capacity warning.
711	     */
712	    private int countOwnersInCity(String city) {
713	        return (int) this.clinicService.findAllOwners().stream()
714	            .filter(existing -> existing.getCity() != null
715	                && existing.getCity().equalsIgnoreCase(city))
716	            .count();
717	    }
718	
719	    /**
720	     * Count the existing owners whose registration date is the given (adjusted business) date.
721	     * Used to enforce the per-day sign-up limit.
722	     */
723	    private int countOwnersRegisteredOn(LocalDate date) {
724	        return (int) this.clinicService.findAllOwners().stream()
725	            .filter(existing -> date.equals(existing.getRegistrationDate()))
726	            .count();
727	    }
728	
729	    /** Fixed public holidays the business-day roll skips. */
730	    private static final Set<LocalDate> HOLIDAYS = Set.of(
731	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
732	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
733	        LocalDate.parse("2026-12-28"));
734	
735	    /**
736	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
737	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
738	     * returned unchanged.
739	     */
740	    private static LocalDate toBusinessDay(LocalDate date) {
741	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
742	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
743	            || HOLIDAYS.contains(date)) {
744	            date = date.plusDays(1);
745	        }
746	        return date;
747	    }
748	
749	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
750	    @Override
751	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
752	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
753	        if (currentOwner == null) {
754	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
755	        }
756	        if (!normalizeEmail(ownerFieldsDto)) {
757	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
758	        }
759	        if (!normalizePostcode(ownerFieldsDto)) {
760	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
761	        }
762	        if (!normalizeAddresses(ownerFieldsDto)) {
763	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
764	        }
765	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
766	        if (normalizedTelephone == null) {
767	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
768	        }
769	        currentOwner.setAddress(ownerFieldsDto.getAddress());
770	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
771	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
772	        currentOwner.setCity(ownerFieldsDto.getCity());
773	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
774	        currentOwner.setLastName(ownerFieldsDto.getLastName());
775	        currentOwner.setTelephone(normalizedTelephone);
776	        currentOwner.setEmail(ownerFieldsDto.getEmail());
777	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
778	        this.clinicService.saveOwner(currentOwner);
779	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
780	    }
