782	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
783	    @Transactional
784	    @Override
785	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
786	        Owner owner = this.clinicService.findOwnerById(ownerId);
787	        if (owner == null) {
788	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
789	        }
790	        // Soft-delete: flag the owner deleted and retain the record so it can still be
791	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
792	        owner.setDeleted(true);
793	        this.clinicService.saveOwner(owner);
794	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
795	    }
